    N: usize,
    seen: HashSet<usize>,
    ans: usize,
}

impl Solver {
    fn dfs(&mut self, v: usize) {
        self.seen.insert(v);

        if self.seen.len() == self.N {
            self.ans += 1;
        }

        for v_next in self.G[v].to_vec() {
            if self.seen.contains(&v_next) { continue; }
            self.dfs(v_next);
            self.seen.remove(&v_next);
        }
    }
}

