    if l == m {
        if can_load(w, k, l) {
            return l;
        } else {
            return r;
        }
    }
    if can_load(w, k, m) {
        bsearch(w, k, l, m)
    } else {
        bsearch(w, k, m, r)
    }
}

fn can_load(w: &[i32], k: i32, p: i32) -> bool {
    let mut i = 0;
    for _ in 0..k {
        let mut load = 0;
        while i < w.len() {
            if load + w[i] > p {
                break;
            }
            load += w[i];
            i += 1;
        }
    }
    i == w.len()
}

