fn dfs(mut v: Vec<usize>, ret:&mut Vec<Vec<usize>>,  c:usize, n: usize){
    // eprintln!("{}, {:?}", c, v);
    if c == 2usize.pow(n as u32) -1 {
        ret.push(v);
        return;
    }

    for i in 0..n{
        if (c >> i) & 1 == 0{
            let mut v = v.clone();
            v.push(i);
            let c = c | (1 << i);
            dfs(v.clone(), ret, c, n);
        }
    }
