        let mut cur_w = 0;
        while i < n && (cur_w + vec[i]) as usize <= p {
            cur_w += vec[i];
            i += 1;
        }
    }

    // 添え字がnに達するなら末尾まで到達したので載せきることが出来た
    i >= n
}

