fn gcd_core(a: u64, b: u64) -> u64 {
    if b == 0 {
        return a;
    }

    return gcd_core(b, a % b);
}

fn _gcd(vec: &Vec<u64>) -> u64 {
    assert!(vec.len() >= 2);

    vec.into_iter().fold(0, |a, &b| gcd_core(a, b))
}

fn lcm_core(a: u64, b: u64) -> u64 {
    let gcd = gcd_core(a, b);
    return (a / gcd) * b;
}

fn lcm(vec: &Vec<u64>) -> u64 {
    vec.into_iter().fold(1, |a, &b| lcm_core(a, b))
}

fn solve<T: std::io::Read>(reader: T) -> u64 {
    input_macro! {
        reader = reader,
        n: u64,
        vec: [u64; n],
    }

    lcm(&vec)
