const MOD: usize = 998244353;
// const MOD: usize = 1_000_000_007;
const INF: i64 = std::i64::MAX/2;

pub struct UnionFind {
    data: Vec<i32>,
}

impl UnionFind {
    pub fn new(n: usize) -> Self{
        UnionFind {
            data: vec![-1;n]
        }
    }
    pub fn root(&mut self, x: usize) -> usize{
        if self.data[x]<0 {
            x
        }
        else {
            let p = self.data[x] as usize;
            self.data[x] = self.root(p) as i32;
            self.data[x] as usize
        }
    }
    pub fn unite(&mut self, x: usize, y: usize){
        let rx = self.root(x);
        let ry = self.root(y);
        if rx!=ry {
            let (rx,ry) = if self.data[rx]<=self.data[ry] {
                (rx,ry)
            }
            else{
                (ry,rx)
            };
            self.data[rx] += self.data[ry];
            self.data[ry] = rx as i32;
        }
    }
    pub fn same(&mut self, x: usize, y: usize) ->  bool{
        self.root(x) == self.root(y)
    }
    pub fn size(&mut self, x: usize) -> i32 {
        let r = self.root(x);
        - self.data[r]
    }
}

fn solve() {
    let (n,q) = read!(usize,usize);
    let tuv = read!(usize,usize,usize;q);
    let mut uf = UnionFind::new(n);
    for (t,u,v) in tuv {
        if t==0 {
            uf.unite(u,v);
        }
        else {
            println!("{}", if uf.same(u,v) {1} else {0});
        }
    }
}

fn run() {
    solve();
}

