        let mut left_c_p = 1;
        let mut right_o_p = (10_000 * self.n as u32) / self.k as u32 + 1; // when max(w_i)=10,000

        while left_c_p < right_o_p {
            let mid_p = (right_o_p + left_c_p) / 2;
            dprintln!("search {} - {} - {}", left_c_p, mid_p, right_o_p);

            if Quiz::check(mid_p, self.k, &self.w) {
