        // greedy 
        let mut r_p = p;
        let mut r_k = k;

        for &wi in w {
           if wi <= r_p {
               // Current truck can take w[i]
               r_p -= wi;
           } else {
               // Consider next truck
               if r_k > 1 && wi <= p {
                   // Next truck can take w[i]
                   r_k -= 1;
                   r_p = p - wi;
               } else {
                   // There is no truck can take wi.
                   return false;
               }
           }
        }
        true
    }
