fn binary_search<F>(ok:usize,ng:usize,isOk:F) -> usize
where F : Fn(usize) -> bool{
    let mut ok = ok as isize;
    let mut ng = ng as isize;
    while (ok-ng).abs() > 1{
        let i = (ok+ng)/2;
        if isOk(i as usize) { ok = i;} else {ng = i;}
    }
    ok as usize
}

