        return;
    }

    is_done[cn] = true;
    if is_done.iter().all(|&x| x == true) {
        *cnt += 1;
    }
    for i in &map[cn] {
        if is_done[*i] == true {
            continue;
        }
        let mut copy_done = is_done.clone();
        dfs(*i, map, cnt, &mut copy_done);
    }
}

