        i -= 1;
    }
    if i <= 0 {
        return false;
    }

    let mut j = arr.len() - 1;
    while arr[j] <= arr[i - 1] {
        j -= 1;
    }
    arr.swap(i - 1, j);

    arr[i..].reverse();

    return true;
