use std::str::FromStr;

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn next_permutation<T: std::cmp::PartialOrd>(arr: &mut std::vec::Vec<T>) -> bool {
    let mut i = arr.len() - 1;
    while i > 0 && arr[i - 1] >= arr[i] {
        i -= 1;
    }
    if i <= 0 {
        return false;
    }

    let mut j = arr.len() - 1;
    while arr[j] <= arr[i - 1] {
        j -= 1;
    }
    arr.swap(i - 1, j);

    arr[i..].reverse();

    return true;
}

#[derive(Debug)]
struct App {
    // input
    n: i32,
    m: i32,
    a: Vec<(i32, i32)>,
}

impl App {
    fn input() -> App {
        let n: i32 = read();
        let m: i32 = read();
        return App {
            n: n,
            m: m,
            a: (0..m).map(|_| (read::<i32>() - 1, read::<i32>() - 1)).collect(),
        };
    }

    fn solve(&mut self) {
        let mut mat = vec![vec![false; self.n as usize]; self.n as usize];
        for &(u, v) in &self.a {
            mat[u as usize][v as usize] = true;
            mat[v as usize][u as usize] = true;
        }

        let mut a: Vec<i32> = (0..self.n).collect();
        let mut ans = 0;
        loop {
            if a[0] == 0 {
                let mut ite = a.windows(2).map(|e| mat[e[0] as usize][e[1] as usize]);
                if ite.all(|f| f) {
                    ans += 1;
                }
            }

            if !next_permutation(&mut a) {
                break;
            }
        }

        println!("{}", ans);
    }
}

fn main() {
    let mut app = App::input();
    app.solve();
}

