pub fn search(a: &[i32], key: i32) -> i32 {
    // 最大積載量Pの最小値は最大荷物の重さ
    let mut min = *a.clone().into_iter().max().unwrap();
    let mut max = a.clone().iter().sum::<i32>();
    let mut ans = max;

    while min < max {
        let mid: i32 = (min + max) / 2;
        let p = need_track(&a, &mid);
        if p > key {
            min = mid + 1;
        } else {
            max = mid;
            ans = if min > max { min } else { max };
        }
    }
    ans
}

