  mod ord_assign {
    use std::cmp::{max, min};

    pub trait OrdAssign: Ord
    where
      Self: Copy,
    {
      fn min_assign(&mut self, other: Self) {
        *self = min(*self, other);
      }

      fn max_assign(&mut self, other: Self) {
        *self = max(*self, other);
      }
    }

    impl<T: Ord + Copy> OrdAssign for T {}
