/// トラックk台のそれぞれの最大積載量がpの時、それが実現可能か判定する
fn check(vec: &Vec<u64>, k: u32, p: usize) -> bool {
    // k台のトラックでそれぞれ、荷物をpを超えるまで合計していく。
    // すべてのトラックについて合計が終わったとき、荷物が余っていればfalse, 荷物を載せきれていればtrueを返す

