        return 1;
    }

    let mut cnt = 0;
    for &to in &edges[v] {
        if !visited.contains(&to) {
            let mut cl = visited.clone();
            cl.insert(to);
            cnt += dfs(edges, &mut cl, to);
        }
    }

    cnt
