/// なお、割り当てにおいては、12|3456|のように、連続する荷物でないと同時に載せられない。
/// 場合の数だと、n-1 C k 通りの組合せが存在するはず。
fn calc_p(k: u32, vec: &Vec<u64>) -> u32 {
    // 二分法を用いるのがいいらしい

    let mut st: usize = 0;
    let mut end: usize = 100000 * 10000 + 1; // 荷物の最大個数*最大重量でpの取りうる最大値
    let mut p: usize = 0;
    while st < end {
        let mid = (st + end) / 2;   // 判定対象のpの計算
        if check(vec, k, mid) {
            p = mid;
            end = mid;
        } else {
            st = mid + 1;
        }
    }

    p as u32
}

