    let token = self.reader.by_ref().bytes().map(|c| c.unwrap() as char)
      .skip_while(|c| c.is_whitespace())
      .take_while(|c| !c.is_whitespace())
      .collect::<String>();
    if token.is_empty() { None } else { token.parse().ok() }
  }
  fn get<T: FromStr>(&mut self) -> T {
    if let Some(v) = self.safe_get() { v } else {
      writeln!(stderr(), "Terminated with EOF").unwrap();
      std::process::exit(0);
    }
  }
}

fn binary_search(vec: &Vec<i64>, k: i64) -> i64 {
  let mut min = vec.clone().into_iter().max().unwrap();
  let mut max = vec.clone().iter().sum::<i64>();
  let mut ans = max;
  while min < max {
    let mid = (min + max) / 2;
    let mut cur_track = 1;
    let mut cur_carry = 0;
    for &w in vec.iter() {
      if cur_carry + w > mid {
        cur_track += 1;
        cur_carry = w;
      }
      else {
        cur_carry += w;
      }
    }
    if cur_track > k {
      min = mid + 1;
    }
    else {
      ans = if ans < mid { ans } else { mid };
      max = mid;
    }
  }
  ans
}

