#[derive(Debug)]
struct Quiz {
    n: usize,    // 1 <= n <= 100,000
    k: usize,    // 1 <= k <= 100,000
    w: Vec<u32>, // 1 <= w[i] <= 10,000, length=n
}

#[derive(Debug)]
struct Answer {
    min_p: u32,
}

trait IntoQuiz {
    fn into_quiz(self) -> Quiz;
}

impl<I: Input> IntoQuiz for I {
    fn into_quiz(mut self) -> Quiz {
        let n: usize = self.parse_next().unwrap();
        let k: usize = self.parse_next().unwrap();
        let w: Vec<u32> = self.parse_next_vec(n).unwrap();
        Quiz { n, k, w }
    }
}

impl Quiz {
    fn solve(self) -> Answer {
        let mut left_c_p = 1;
        let mut right_o_p = (10_000 * self.n as u32) / self.k as u32 + 1; // when max(w_i)=10,000

        while left_c_p < right_o_p {
            let mid_p = (right_o_p + left_c_p) / 2;
            dprintln!("search {} - {} - {}", left_c_p, mid_p, right_o_p);

            if Quiz::check(mid_p, self.k, &self.w) {
                // search left
                dprintln!(" {} is ok. next search left.", mid_p);
                right_o_p = mid_p;
            } else {
                // search right
                dprintln!(" {} is ng. next search right.", mid_p);
                left_c_p = mid_p + 1;
            }
        }

        Answer{ min_p : right_o_p }
    }

    fn check(p: u32, k: usize, w: &Vec<u32>) -> bool {
        // greedy 
        let mut r_p = p;
        let mut r_k = k;

        for &wi in w {
           if wi <= r_p {
               // Current truck can take w[i]
               r_p -= wi;
           } else {
               // Consider next truck
               if r_k > 1 && wi <= p {
                   // Next truck can take w[i]
                   r_k -= 1;
                   r_p = p - wi;
               } else {
                   // There is no truck can take wi.
                   return false;
               }
           }
        }
        true
    }
}

impl Answer {
    fn print(self) {
        println!("{}", self.min_p);
    }
}

