use std::cmp::Ordering::*;
fn binary_search<F>(min: usize, max: usize, mut f: F) -> (usize, usize)
where
    F: FnMut(usize) -> std::cmp::Ordering,
{
    let mut left = min;
    let mut right = max;

    while right - left > 1 {
        let center = (left + right) / 2;
        match f(center) {
            Less => left = center + 1,
            Equal => return (center, 0),
            Greater => right = center,
        }
    }

    match f(left) {
        Less => (left, 1),
        Equal => (left, 0),
        Greater => (left - 1, 1),
    }
}


