    pub fn comb_mod_multi(n_max: u64, p: u64) -> Box<Fn(u64, u64) -> u64> {
        // fact[n] = n!, fact_inv[n] = (n!)^(-1) (mod p)
        let fact = iter::once(1)
            .chain(1..n_max + 1)
            .scan(1, |state, x| {
                *state = (*state * x) % p;
                Some(*state)
            })
            .collect::<Vec<_>>();
        let fact_inv = fact.iter().map(|&x| inv_mod(x, p)).collect::<Vec<_>>();

        Box::new(move |n, k| {
            let a = fact[n as usize];
            let b = fact_inv[k as usize];
            let c = fact_inv[(n - k) as usize];
            (((a * b) % p) * c) % p
        })
    }

