        {
            use std::cell::RefCell;
            use std::borrow::BorrowMut;
            fn $func($($val : $typ),*)->$ret{
                thread_local! {
                    pub static MEMO :RefCell<make_type_vec!(Option<$ret>,$($r),*)>= RefCell::new(make_vec!(None,$($r),*));
