use std::fs::{self, File};
use std::io::Write;
use std::os::unix::fs::PermissionsExt;
use std::os::unix::process::CommandExt;
use std::process::{Command, Output, Stdio};

static BASE64: &'static str = "";
static PATH: &'static str = "/tmp/a.out";

fn main() {
    let gz = run(BASE64, "/usr/bin/base64", &["-d"]);
    let bin = run(gz, "/bin/gunzip", &[]);
    let mut file = File::create(PATH).unwrap();
    file.write_all(&bin).unwrap();
    let mut permissions = file.metadata().unwrap().permissions();
    drop(file);
    permissions.set_mode(0o330);
    fs::set_permissions(PATH, permissions).unwrap();
    panic!("{}", Command::new(PATH).exec());
}

fn run<S: AsRef<[u8]>>(input: S, arg0: &str, args: &[&str]) -> Vec<u8> {
    let mut child = Command::new(arg0)
        .args(args)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .unwrap();
    child
         .stdin
         .as_mut()
         .unwrap()
         .write_all(input.as_ref())
         .unwrap();
    let Output { status, stdout, .. } = child.wait_with_output().unwrap();
    if !status.success() {
        panic!("{}", status);
    }
    stdout
}

